let missionQueue=[],missionActive=null,contractCelebrated=false;
function clearMissionNotices(){missionQueue=[];missionActive=null;contractCelebrated=false;document.querySelector('.mission-notice')?.remove();}
function missionNotice(title,name,detail='',contract=false,kind=''){if(kind==='technology')missionQueue=missionQueue.filter(x=>x.kind!=='technology');if(missionQueue.some(x=>x.title===title&&x.name===name))return;missionQueue.push({title,name,detail,contract,kind,created:engine?.time||0,priority:kind==='record'?4:kind==='synergy'||contract?3:kind==='technology'?1:2});missionQueue.sort((a,b)=>b.priority-a.priority);missionQueue=missionQueue.slice(0,6);}
function updateMissionNotice(dt){
 if(!isRunning||!engine)return;
 if(engine.state==='dead'){if(missionActive||missionQueue.length)clearMissionNotices();return;}
 if(engine.contractDone&&!contractCelebrated){contractCelebrated=true;const c=engine.contractProgress();missionNotice('КОНТРАКТ ВЫПОЛНЕН',c.name,t('Награда по итогам попытки')+': +'+c.reward+' ◈',true);}
 if(engine.state!=='playing'||!modal.classList.contains('hidden')||bossMoment||engine.time<(engine.boss?.vulnerableUntil||0))return;
 missionQueue=missionQueue.filter(x=>x.contract||engine.time-x.created<18);
 if(missionActive){missionActive.life-=dt;missionActive.el.style.setProperty('--remaining',Math.max(0,missionActive.life/3.6));if(missionActive.life<=0){missionActive.el.remove();missionActive=null;}}
 if(!missionActive&&missionQueue.length){const item=missionQueue.shift(),el=document.createElement('div');el.className='mission-notice'+(item.contract?' contract':'')+(item.kind?' '+item.kind:'');el.setAttribute('role','status');el.setAttribute('aria-live','polite');el.innerHTML='<span class="mission-emblem" aria-hidden="true">'+(item.kind==='synergy'?'ϟ':item.kind==='record'?'✦':item.kind==='technology'?'⬡':item.contract?'◇':'✓')+'</span><div><small>'+esc(t(item.title))+'</small><strong>'+esc(t(item.name))+'</strong>'+(item.detail?'<p>'+esc(t(item.detail))+'</p>':'')+'</div><i aria-hidden="true"></i>';document.body.append(el);missionActive={el,life:3.6};audio.play(item.kind==='record'?'record':item.kind==='synergy'?'synergyUnlock':item.kind==='technology'?'moduleInstall':'objectiveComplete');}
}
