function uiIcon(symbol){const paths={'▱':'m6 5 15 2-3 7-15-2Zm-3 10 15 2-2 5-15-2','◷':'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18M12 6v6l4 2','⤨':'M3 7h14l-4-4m4 4-4 4M21 17H7l4-4m-4 4 4 4','⌁':'m2 14 5-7 5 10 5-10 5 7',"⬡":"m12 2 9 5v10l-9 5-9-5V7Zm0 5 5 3v5l-5 3-5-3v-5Z","✳":"M12 2v5m0 10v5M2 12h5m10 0h5M5 5l4 4m6 6 4 4M5 19l4-4m6-6 4-4M10 10h4v4h-4Z","✦":"m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z","◇":"m12 2 9 10-9 10L3 12Zm0 5v10","⬢":"m12 3 8 5v8l-8 5-8-5V8ZM8 10l4 7 4-7","✧":"m12 2 2 8 8 2-8 2-2 8-2-8-8-2 8-2","⟡":"m12 2 8 10-8 10-8-10ZM12 7v10M8 12h8","◈":"m12 2 10 10-10 10L2 12ZM12 8l4 4-4 4-4-4Z","✴":"M12 2v7m0 6v7M2 12h7m6 0h7M5 5l5 5m4 4 5 5M5 19l5-5m4-4 5-5","✺":"M12 2v4m0 12v4M2 12h4m12 0h4M5 5l3 3m8 8 3 3M5 19l3-3m8-8 3-3M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8","⚡":"m13 2-9 12h7l-1 8 10-13h-7Z",'gamepad':'M7 7h10c3 0 5 10 3 11-2 1-4-3-5-3H9c-1 0-3 4-5 3C2 17 4 7 7 7Z M6 11h5m-2.5-2.5v5M16 10v1m2 2v1','↻':'M19 8a8 8 0 1 0 1 8 M19 3v5h-5','◔':'M18 5a9 9 0 0 1 0 14 M12 3v18','✚':'M12 4v16M4 12h16','ϟ':'m14 2-9 12h6l-1 8 9-12h-6Z','⇢':'M3 8h14m-4-4 4 4-4 4M3 17h18m-4-4 4 4-4 4','◒':'M12 3a9 9 0 1 0 0 18V3Z','∞':'M12 12c-8-12-12 10-4 4l8-8c8-6 12 16-4 4','△':'m12 3 10 18H2Z','◎':'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8','⌖':'M12 2v20M2 12h20M5 5h14v14H5Z','⋈':'m3 5 18 14V5L3 19Z','↗':'M5 19 19 5M9 5h10v10','☼':'M12 7a5 5 0 1 0 0 10 5 5 0 0 0 0-10M12 1v3m0 16v3M1 12h3m16 0h3'};return `<svg class="svg-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[symbol]||'m12 3 9 5v8l-9 5-9-5V8Z M8 12h8m-4-4v8'}"/></svg>`;}
const audio=new CoreAudio.AudioSystem(()=>save.settings);
function header(title,eyebrow,desc,chip=''){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h2>${title}</h2><p>${desc}</p></div>${chip?`<div class="balance-chip">${chip}</div>`:''}</div>`;}
const cores=[{id:'standard',name:'Стандарт',desc:'Начальные характеристики без дополнительных усилений.'},{id:'mirror',name:'Зеркало',desc:'Идеальное отражение +25%, весь урон отражения −10%.'},{id:'storm',name:'Шторм',desc:'Стартовая цепная молния, урон отражения −20%.'},{id:'bastion',name:'Бастион',desc:'Щит +10°, скорость поворота −18%.'}];
function corePicker(){return `<div class="core-picker"><small>КОНФИГУРАЦИЯ ЯДРА</small><div>${cores.map(c=>`<button data-core="${c.id}" class="${(mode==='skill'?'standard':save.settings.core||'standard')===c.id?'selected':''}" title="${c.desc}" aria-pressed="${(mode==='skill'?'standard':save.settings.core||'standard')===c.id}" ${mode==='skill'?'disabled':''}>${c.name}</button>`).join('')}</div><p>${mode==='skill'?'В чистом навыке используется стандартное ядро.':cores.find(c=>c.id===(mode==='skill'?'standard':save.settings.core||'standard')).desc}</p></div>`;}
function controllerStatus(){return !padState.available?'Геймпад недоступен в этом браузере.':!padState.connected?'Подключите геймпад и нажмите на нём любую кнопку.':padState.standard?'Геймпад подключён: '+padState.id:'Нестандартная раскладка: доступны стики, кнопки зависят от браузера.';}
function updateControllerStatus(){const icon=$('#controller-icon');if(icon){icon.classList.toggle('connected',padState.connected);icon.setAttribute('title',t(controllerStatus()));icon.setAttribute('aria-label',t(controllerStatus()));}const status=$('#controller-status');if(status)status.textContent=t(controllerStatus());}
function controllerItems(){const roots=!modal.classList.contains('hidden')?[modal]:[screen];const items=roots.flatMap(el=>[...el.querySelectorAll('button:not([disabled]),input[type="range"],input[type="checkbox"],summary')]);if(modal.classList.contains('hidden')&&!isRunning)items.push(...$$('.nav-button'),...$$('.topbar-controls button'));return items.filter(el=>!el.disabled&&(typeof el.getClientRects!=='function'||el.getClientRects().length));}
function spatialChoice(items,selected,nav){const a=selected.getBoundingClientRect(),ax=a.left+a.width/2,ay=a.top+a.height/2;const list=items.filter(el=>el!==selected).map(el=>{const b=el.getBoundingClientRect(),dx=b.left+b.width/2-ax,dy=b.top+b.height/2-ay;const main=nav==='right'?dx:nav==='left'?-dx:nav==='down'?dy:-dy,cross=nav==='right'||nav==='left'?Math.abs(dy):Math.abs(dx);return {el,main,score:main+cross*2.5};}).filter(v=>v.main>1).sort((a,b)=>a.score-b.score);return list[0]?.el||items[(items.indexOf(selected)+(nav==='left'||nav==='up'?-1:1)+items.length)%items.length];}
function controllerMenu(nav,confirm){const items=controllerItems();if(!items.length)return;let selected=items.includes(document.activeElement)?document.activeElement:null;
 if(!selected)selected=items.find(el=>el.dataset.action==='start'||el.dataset.action==='resume'||el.dataset.action==='restart')||items[0];
 if(nav){if(selected.tagName==='INPUT'&&selected.type==='range'&&(nav==='left'||nav==='right')){selected.value=Math.max(Number(selected.min||0),Math.min(Number(selected.max||100),Number(selected.value)+(nav==='right'?5:-5)));selected.dispatchEvent(new Event('input',{bubbles:true}));return;}
 const direction=nav==='left'||nav==='up'?-1:1;selected=spatialChoice(items,selected,nav);for(const el of items)el.classList.remove('pad-focus');selected.classList.add('pad-focus');selected.focus({preventScroll:true});selected.scrollIntoView?.({block:'nearest',inline:'nearest'});}
 if(confirm)selected.click();
}
function controllerBack(){if(confirmCallback&&confirmationInfo){actions.cancel();return;}if(isRunning&&['upgrade','route','specialization','victory'].includes(engine?.state))return;if(isRunning&&engine?.state==='playing')pause();else if(isRunning&&engine?.state==='paused')resume();else goPage('home');}
function pollController(ms){if(!windowFocused||document.hidden)return null;const menu=!isRunning||engine?.state!=='playing';controller.deadzone=save.settings.deadzone||.22;const next=controller.poll(ms,menu),changed=next.changed;
 if(changed&&inputOwner==='gamepad'&&isRunning&&engine?.state==='playing'){input.angle=undefined;pause();toast('Геймпад отключён. Игра на паузе.');}
 const statusChanged=changed||next.available!==padState.available||next.standard!==padState.standard;padState=next;if(statusChanged)updateControllerStatus();if(next.confirm||next.pause||next.back||next.overload||next.nav)inputOwner='gamepad';
 if(next.pause){audio.unlock();if(engine?.state==='playing'&&isRunning)pause();else if(engine?.state==='paused'&&isRunning&&!confirmationInfo)resume();return null;}
 if(next.back){audio.unlock();controllerBack();return null;}
 if(menu){if(next.confirm||next.nav)audio.unlock();if(next.nav||next.confirm)controllerMenu(next.nav,next.confirm);return null;}
 if(next.overload){audio.unlock();engine?.overload();inputOwner='gamepad';}
 return next;
}
let researchTarget='';try{researchTarget=browserStorage.getItem(store.key+'-research-target')||'';}catch{}
function researchOptions(){return D.tech.filter(x=>(save.tech[x.id]||0)<x.max).map(def=>({def,cost:D.cost(def,save.tech[def.id]||0),missing:(def.requires||[]).filter(id=>!save.tech[id])}));}
function researchPlan(){const selected=researchOptions().find(x=>x.def.id===researchTarget);return selected||nextResearch();}
function researchGuide(){return '<div class="research-directions">'+[['Корпус','Выживаемость','Больше здоровья и восстановление'],['Щит','Отражения','Шире щит и сильнее ответный удар'],['Реактор','Энергия','Больше возможностей за попытку']].map(([tab,name,desc])=>'<button data-shop-tab="'+tab+'" class="'+(shopTab===tab?'selected':'')+'" aria-pressed="'+(shopTab===tab)+'"><strong>'+name+'</strong><span>'+desc+'</span></button>').join('')+'</div><div class="research-goal">'+progressNote()+'</div>';}
function nextResearch(){const options=D.tech.filter(x=>(save.tech[x.id]||0)<x.max&&!(x.requires||[]).some(id=>!save.tech[id])).map(x=>({def:x,cost:D.cost(x,save.tech[x.id]||0)})).sort((a,b)=>a.cost-b.cost);return options[0];}
function progressNote(){const next=researchPlan();return next?'<div class="progress-note"><span>'+uiIcon(next.def.icon)+'</span><div><small>'+(next.def.id===researchTarget?'Ваша цель':'Следующее исследование')+'</small><strong>'+next.def.name+'</strong><p>'+(next.missing?.length?'Сначала откройте: '+next.missing.map(id=>t(D.tech.find(x=>x.id===id).name)).join(', '):save.shards>=next.cost?'Можно открыть сейчас':'Осталось осколков: '+num(next.cost-save.shards))+'</p></div><button class="text-button" data-research-focus="'+next.def.id+'" aria-label="Открыть развитие">↗</button></div>':'';}
function home(){const best=save.currentBests[mode]||{},date=C.dailyKey(),daily=save.dailyRecords?.[date],core=cores.find(c=>c.id===(mode==='skill'?'standard':save.settings.core||'standard')),contract=D.contracts.find(c=>c.id===(save.settings.contract||'none'))||D.contracts[0];return '<div class="home command-home modern-home sentient-home"><section class="home-intro"><div class="eyebrow mind-link"><i class="live-dot"></i> СВЯЗЬ С ЯДРОМ <span>07 / ИСТОК</span></div><h1>CORE<span class="title-rule" aria-hidden="true"></span></h1><div class="title-sub">ЗАЩИТНЫЙ ИНТЕЛЛЕКТ</div><p class="hero-copy">Я ещё горю.<br>Держи рубеж.</p><p class="mind-brief">Один щит. Последний источник света.</p><div class="mode-label"><span>РЕЖИМ: '+modes[mode].name+'</span><button class="text-button" data-page="modes">Сменить ↗</button></div><button class="launch" data-action="start"><span><b>В БОЙ</b><small>Начать попытку</small></span><kbd>ENTER</kbd><span class="launch-arrow">↗</span></button><div class="control-tip"><span>Мышь · касание · клавиатура · геймпад</span></div><div class="home-record"><span>Личный рекорд</span><strong>'+time(best.time)+'</strong><small>'+num(best.score)+' '+t('очков')+'</small></div></section><div class="home-reactor mind-display" aria-hidden="true"><div class="projection-caption"><span>РЕАКТОР В СЕТИ</span><strong>'+core.name+'</strong></div><div class="mind-designation">ИСТОК<span>ЗАЩИТНЫЙ ИНТЕЛЛЕКТ</span></div><div class="projection-index">CORE / 07</div><div class="mind-axis"><i></i><span>КОНТУР СДЕРЖИВАНИЯ</span></div></div><div class="home-bottom"><details class="setup-panel mind-setup" data-setup="core"><summary><span class="setup-number">01</span><span><small>ВАШЕ ЯДРО</small><strong>'+core.name+'</strong></span><i aria-hidden="true">+</i></summary>'+corePicker()+'</details><details class="setup-panel mind-setup" data-setup="contract"><summary><span class="setup-number">02</span><span><small>КОНТРАКТ · НАГРАДА И ШТРАФ</small><strong>'+contract.name+'</strong></span><i aria-hidden="true">+</i></summary>'+contractPicker()+'</details><section class="daily-panel"><div><span class="eyebrow">ИСПЫТАНИЕ ДНЯ · '+date+'</span><h3>Один день. Равный старт.</h3><p>Общий сценарий дня, базовое ядро и отдельный рекорд. Без постоянных бонусов и наград. Новый день — в 00:00 UTC.</p>'+(daily?'<small>Ваш рекорд: '+num(daily.score)+' '+t('очков')+' · '+time(daily.time)+'</small>':'')+'</div>'+button('daily','Принять вызов ↗')+'</section>'+progressNote()+'</div></div>';}
