function drawFacetedCore(clock,col,markers=true){
 // Six vertices, eight faces: visual-only rotation never touches the game RNG.
 const yaw=clock*.38,tilt=.48,vertices=[[0,-67,0],[67,0,0],[0,0,67],[-67,0,0],[0,0,-67],[0,67,0]].map(([x,y,z])=>{const rx=x*Math.cos(yaw)+z*Math.sin(yaw),rz=z*Math.cos(yaw)-x*Math.sin(yaw);return {x:rx,y:y*Math.cos(tilt)-rz*Math.sin(tilt),z:y*Math.sin(tilt)+rz*Math.cos(tilt)};});
 const faces=[];for(let i=1;i<=4;i++){const j=i===4?1:i+1;faces.push([0,i,j],[5,j,i]);}faces.sort((a,b)=>a.reduce((n,i)=>n+vertices[i].z,0)-b.reduce((n,i)=>n+vertices[i].z,0));
 for(const face of faces){const depth=face.reduce((n,i)=>n+vertices[i].z,0)/3;ctx.beginPath();face.forEach((v,i)=>{const p=vertices[v];if(i)ctx.lineTo(p.x,p.y);else ctx.moveTo(p.x,p.y);});ctx.closePath();ctx.fillStyle=depth>0?'#123b55b8':'#071420b0';ctx.fill();ctx.strokeStyle=col+(depth>0?'ed':'55');ctx.lineWidth=depth>0?1.7:.8;ctx.stroke();}
 if(markers){glow(col,14);circle(0,0,7,'#e7ffff',2);ctx.shadowBlur=0;for(const p of vertices)circle(p.x,p.y,p.z>0?2.4:1.3,col,1.4);}
}
