 for(const s of stars){ctx.globalAlpha=s.a*(.65+Math.sin(t*.4+s.x*20)*.2);ctx.fillStyle='#9ec6d8';ctx.fillRect(s.x*width,s.y*height,s.r,s.r);}ctx.globalAlpha=1;
 const ambient=!isRunning;if(!ambient){const color=sectorLooks[sectorIndex(engine)][1],wash=ctx.createRadialGradient(width*.5,height*.5,50,width*.5,height*.5,Math.max(width,height)*.65);wash.addColorStop(0,color+'0c');wash.addColorStop(1,color+'00');ctx.fillStyle=wash;ctx.fillRect(0,0,width,height);}if(ambient){if(page==='home')drawMindBackdrop(t);else drawMenuCity(t);}let drawScale=scale,drawX=cx,drawY=cy;
