 ctx.save();ctx.translate(drawX+(shake?Math.sin(t*109)*shake:0),drawY+(shake?Math.cos(t*127)*shake*.6:0));ctx.scale(drawScale,drawScale);if(!(ambient&&page==='home')){drawSectorBackdrop(t,ambient);arenaRings(t,ambient);if(!ambient)drawSectorIdentity(engine);}
