function drawDeathReplay(dt){const c=$('#death-replay');if(!c||!engine?.replay.length)return;if(replayPlaying)replayClock=(replayClock+dt)%2.5;const frames=engine.replay,at=frames[0].time+Math.min(1.8,replayClock),f=frames.filter(f=>f.time<=at).at(-1)||frames[0],g=c.getContext('2d');g.fillStyle='#080e17';g.fillRect(0,0,560,360);g.save();g.translate(280,180);g.scale(2,2);g.strokeStyle='#355969';g.lineWidth=1;g.beginPath();g.arc(0,0,65,0,C.TAU);g.stroke();g.fillStyle='#78dfff';g.beginPath();g.arc(0,0,24,0,C.TAU);g.fill();g.strokeStyle='#70f5d1';g.lineWidth=7;g.beginPath();g.arc(0,0,65,f.angle-(f.width||engine.width)/2,f.angle+(f.width||engine.width)/2);g.stroke();if(f.secondary){g.beginPath();g.arc(0,0,65,f.angle+Math.PI-f.secondary/2,f.angle+Math.PI+f.secondary/2);g.stroke();}if(f.barrier){g.strokeStyle='#c7a2ff';g.beginPath();g.arc(0,0,55,0,C.TAU);g.stroke();}for(const p of f.bullets){g.fillStyle='#ff687e';g.beginPath();g.arc(p.x,p.y,3.7,0,C.TAU);g.fill();}for(const a of f.beams){g.strokeStyle='#ff687e88';g.lineWidth=2;g.beginPath();g.moveTo(0,0);g.lineTo(Math.cos(a)*140,Math.sin(a)*140);g.stroke();}for(const a of f.feints||[]){g.setLineDash([3,5]);g.strokeStyle='#b48aff';g.beginPath();g.moveTo(0,0);g.lineTo(Math.cos(a)*140,Math.sin(a)*140);g.stroke();g.setLineDash([]);}if(f.time>=engine.lastHit.time-.08){const a=engine.lastHit.angle;g.strokeStyle='#ffd27a';g.lineWidth=2;g.beginPath();g.moveTo(Math.cos(a)*25,Math.sin(a)*25);g.lineTo(Math.cos(a)*95,Math.sin(a)*95);g.stroke();}const point=C.pos(engine.lastHit.angle,65);g.strokeStyle='#ffd27a';g.lineWidth=2;g.beginPath();g.arc(point.x,point.y,8,0,C.TAU);g.stroke();g.restore();const el=$('#replay-time');if(el)el.textContent=(f.time-engine.lastHit.time).toFixed(2)+' '+t('с');}
function frame(ms){const dt=Math.min(.05,lastTime?(ms-lastTime)/1000:0);lastTime=ms;elapsed+=dt;coreDamageGlow=Math.max(0,coreDamageGlow-dt);if(bossMoment&&engine?.state==='playing'){bossMomentLife-=dt;if(bossMomentLife<=0)clearBossMoment();}shake=Math.max(0,shake-dt*23);const pad=pollController(ms);audio.update(!isRunning?'menu':engine?.state==='paused'||engine?.state==='upgrade'?'paused':engine?.state==='dead'?'result':engine?.boss?'boss':'combat',isRunning&&engine?Math.min(1,engine.time/600):0,isRunning?sectorIndex(engine):0);if(isRunning&&engine){const axis=Number(keys.has('d')||keys.has('в')||keys.has('arrowright'))-Number(keys.has('a')||keys.has('ф')||keys.has('arrowleft'));let turnAxis=axis;if(axis){inputOwner='keyboard';input.angle=undefined;}else if(pad?.active){inputOwner='gamepad';if(pad.axis){turnAxis=pad.axis;input.angle=engine.angle;}else if(Number.isFinite(pad.angle))input.angle=pad.angle;}engine.update(dt,{axis:turnAxis,angle:input.angle});if(inputOwner==='gamepad'&&turnAxis)input.angle=engine.angle;handleEvents();updateMissionNotice(dt);if(ms-lastHud>85){updateHud();lastHud=ms;}}for(const l of labels)l.life-=dt;for(let i=labels.length-1;i>=0;i--)if(labels[i].life<=0)labels.splice(i,1);render(elapsed);if(engine?.state==='dead')drawDeathReplay(dt);requestAnimationFrame(frame);}
